	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	deleted_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(origin_warehouse_id) REFERENCES warehouse (id) ON DELETE SET NULL, 
	FOREIGN KEY(carrier_id) REFERENCES carrier (id) ON DELETE SET NULL, 
	FOREIGN KEY(vehicle_id) REFERENCES vehicle (id) ON DELETE SET NULL
);

